  if(!result?.ok){setError(result?.error||'操作未完成，请检查当前任务状态。');return;}
  setError('');setDialog(null);setReason('');
  const text={saveDraft:'标注草稿已保存',submit:'标注已提交审核',reject:'样本已退回修改',resubmit:'返工结果已重新提交审核',approve:'样本已审核通过',reopen:'样本已重新进入待标注队列，已有质检结果已失效'};
