  {dialog==='assign'&&<Modal title="分配标注任务" description={`${batch.name} · 选择模拟标注人`} onClose={()=>setDialog(null)} footer={<><Button onClick={()=>setDialog(null)}>取消</Button><Button variant="primary" disabled={assignScope==='unassigned'&&!counts.unassigned} onClick={assign}>确认分配</Button></>}><Field label="分配范围"><select value={assignScope} onChange={event=>setAssignScope(event.target.value)}><option value="unassigned">尚未分配的待标注记录（{counts.unassigned} 条）</option><option value="todo">全部待标注记录（{counts.todo} 条）</option>{selected?.status==='todo'&&<option value="selected">当前样本（{selected.id}）</option>}</select></Field><Field label="模拟标注人"><select value={assignee} onChange={event=>setAssignee(event.target.value)}><option>李一</option><option>陈思</option><option>演示管理员</option></select></Field><p className="dv-help">分配只更新本批次待标注记录，并校验模拟角色与项目权限；未接入真实登录后端。</p>{error&&<p className="dv-action-error" role="alert">{error}</p>}</Modal>}
  {(dialog==='reject'||dialog==='reopen')&&selected&&<Modal title={dialog==='reject'?'退回修改':'重新标注'} description={`样本 ${selected.id} · ${batch.name}`} onClose={()=>setDialog(null)} footer={<><Button onClick={()=>setDialog(null)}>取消</Button><Button variant={dialog==='reject'?'danger':'primary'} disabled={!reason.trim()} onClick={()=>act(dialog,{note:reason.trim()})}>{dialog==='reject'?'确认退回':'确认重新标注'}</Button></>}><Field label={dialog==='reject'?'退回原因':'重新标注原因'} required><textarea rows={4} autoFocus value={reason} onChange={event=>setReason(event.target.value)} placeholder="请说明需要修正的内容和判断依据"/></Field>{dialog==='reopen'&&<div className="dv-state-notice warning"><IconInfoCircle size={20}/><div><strong>本条记录将返回待标注</strong><p>当前质检结果需要重做。已经发布的版本保留原记录和原标签。</p></div></div>}{error&&<p className="dv-action-error" role="alert">{error}</p>}</Modal>}
  {guide&&<Modal title={batch.specSnapshot?.name||'本批次标注规范'} description={`冻结规范 ${batch.specSnapshot?.version} · ${batch.taskSpecVersionId}`} wide onClose={()=>setGuide(false)} footer={<Button variant="primary" onClick={()=>setGuide(false)}>已了解</Button>}><div className="dv-guideline"><h4>标注指南</h4><p>{batch.specSnapshot?.guide}</p><h4>审核要求</h4><p>{batch.specSnapshot?.review}</p>{labels.map(item=><React.Fragment key={item.name}><h4>{item.name}</h4><p>{item.description||'以标注指南中的约定为准。'}</p></React.Fragment>)}</div></Modal>}
