function TextBatchQualityView({batch,onTextAction,onNavigate,onToast}){
 const [publishOpen,setPublishOpen]=useState(false),[note,setNote]=useState('完成本批次人工审核与质量检查，发布用于模型训练的数据版本。'),[consent,setConsent]=useState(false),[receiptId,setReceiptId]=useState(null),[error,setError]=useState(''),[preview,setPreview]=useState(null);
 const counts=textCounts(batch),quality=batch.quality,versions=batch.versions||[],labels=textLabels(batch),receipt=versions.find(version=>version.id===receiptId&&version.sourceRevision===batch.revision);
 const currentQuality=quality?.revision===batch.revision,ready=quality?.status==='passed'&&currentQuality&&quality.count===counts.approved,alreadyPublished=versions.some(version=>version.sourceRevision===batch.revision),nextVersion=`v0.${versions.length+1}`;
 const go=(view,extra={})=>onNavigate(view,{...textScope(batch),...extra});
 const run=()=>{const result=onTextAction(batch.datasetId,{type:'checkQuality'});if(!result?.ok){setError(result?.error||'检查未完成，请先处理当前记录。');return;}setError('');setReceiptId(null);onToast(result.batch.quality?.status==='passed'?'本批次质量检查通过':'质量检查发现问题，请处理后重新检查',result.batch.quality?.status==='passed'?'success':'warning')};
 const publish=()=>{if(!consent)return;const result=onTextAction(batch.datasetId,{type:'publish',note,owner:'演示管理员'});if(!result?.ok){setError(result?.error||'发布未完成，请检查发布条件。');return;}setError('');setReceiptId(result.version.id);setPublishOpen(false);onToast(`${batch.name} ${result.version.version} 已生成独立发布快照`)};
 const checks=(currentQuality&&quality?.status!=='stale'?quality?.checks:null)||[{id:'structure',name:'记录完整性',detail:'检查文本、编号与标签是否完整'},{id:'labels',name:'标签规范',detail:'检查标签是否属于本批次冻结规范'},{id:'duplicates',name:'重复内容',detail:'检查待发布文本是否重复'},{id:'review',name:'审核状态',detail:'仅纳入审核通过的记录'},{id:'lineage',name:'来源关系',detail:'检查项目、批次与规范版本'}];
 if(batch.stage!=='cleaned')return <div><PageHeader title="质量检查" description={batch.name}/><TextBatchIdentity batch={batch}/><Panel><Empty title="本批次尚未完成清洗与审核" description="先完成清洗，再标注和审核同一批记录。"><Button variant="primary" onClick={()=>go('processing')}>前往本批次清洗</Button><Button onClick={()=>go('datasets')}>返回本数据集</Button></Empty></Panel></div>;
 return <div className="dv-quality dv-text-quality"><PageHeader title="质量检查" description={`${batch.name} · 发布前检查`}><Button icon={IconArrowLeft} onClick={()=>go('review')}>返回本批次审核</Button></PageHeader><StepBar steps={stages} current={receipt?4:3}/><TextBatchIdentity batch={batch}/>
  {quality&&(!currentQuality||quality.status==='stale')&&<div className="dv-state-notice warning dv-quality-stale" role="status"><IconAlertCircle size={21}/><div><strong>工作批次已变化，原质检结果已失效</strong><p>请按当前记录重新检查，才能发布新的数据版本。</p></div></div>}
  <div className="dv-quality-grid"><section className="panel"><div className="panel-heading"><div><h2>本次检查范围</h2><p>{batch.batchId} · 当前修订 {batch.revision}</p></div><Badge tone={ready?'mint':quality?.status==='failed'?'red':'amber'}>{ready?'检查通过':quality?.status==='failed'&&currentQuality?'检查未通过':quality?'需要重新检查':'待检查'}</Badge></div><div className="dv-quality-body"><div className="dv-quality-scope"><div><strong>{counts.approved}</strong><span>条审核通过记录</span></div><div><span>暂不纳入</span><b>{counts.total-counts.approved} 条</b><small>待标注 {counts.todo} · 待审核 {counts.review} · 返工 {counts.rework}</small></div></div><div className="dv-soft-note"><IconInfoCircle size={18}/><p>本次将冻结已通过审核的记录。其他任务留在当前工作批次继续处理；后续修改不会影响历史发布版本。</p></div><div className="dv-section-heading dv-check-heading"><h3>质量规则</h3><span className="muted small">本批次实际演示记录</span></div><div className="dv-rule-list">{checks.map(check=>{const checked=quality&&currentQuality&&quality.status!=='stale';return <div className="dv-rule" key={check.id}><span className={`dv-rule-icon ${checked?(check.passed?'passed':'failed'):''}`}>{checked?(check.passed?<IconCheck size={18}/>:<IconX size={18}/>):<IconShieldCheck size={19}/>}</span><div><h3>{check.name}</h3><p>{check.detail}</p></div><div className="dv-rule-result">{checked?<b className={check.passed?'':'dv-failed-text'}>{check.passed?'通过':'未通过'}</b>:<span>等待检查</span>}</div></div>})}</div>{quality?.checkedAt&&<p className="dv-help">上次检查：{formatTextBatchTime(quality.checkedAt)} · 来源修订 {quality.revision}{(!currentQuality||quality.status==='stale')?' · 已过期':''}</p>}{!counts.approved&&<div className="dv-state-notice warning"><IconInfoCircle size={19}/><div><strong>没有可检查的审核通过记录</strong><p>请返回本批次完成至少一条记录的标注和审核。</p></div></div>}{error&&<p className="dv-action-error" role="alert">{error}</p>}<div className="dv-quality-actions"><span>本地校验记录、标签与来源；不执行外部质量检测。</span><Button variant={ready?'secondary':'primary'} icon={quality?IconRefresh:IconPlayerPlay} disabled={!counts.approved} onClick={run}>{quality?'重新检查':'运行质量检查'}</Button></div></div></section>
   <aside><Panel title="发布准备"><div className="dv-publish-summary"><IconShieldCheck size={38} stroke={1.3}/><h3>{receipt?'发布快照已生成':alreadyPublished?'当前修订已发布':ready?'已具备发布条件':'完成检查后即可发布'}</h3><p>{receipt?`${receipt.version} 保存了 ${receipt.count} 条审核通过记录，可直接用于训练选择。`:alreadyPublished?'同一修订无需重复发布。继续处理工作批次后，可重新检查并创建下一版本。':'数据版本保留记录、标签、规范和来源，供后续训练引用。'}</p><div className="dv-description-grid"><span>数据类型</span><b>文本分类</b><span>标签规范</span><b>{batch.specSnapshot?.version} · {labels.length} 个标签</b><span>{receipt?'发布版本':'下一版本'}</span><b>{receipt?.version||nextVersion}</b></div>{receipt?<><Button variant="primary" onClick={()=>go('training',{versionId:receipt.id})}>使用此版本训练</Button><Button onClick={()=>setPreview(receipt)}>查看发布快照</Button></>:<Button variant="primary" disabled={!ready||alreadyPublished} onClick={()=>{setConsent(false);setError('');setPublishOpen(true)}}>准备发布<IconArrowRight size={16}/></Button>}<Button variant="ghost" onClick={()=>go('datasets',{tab:'versions'})}>查看本数据集版本</Button></div></Panel><div className="dv-soft-note"><IconHistory size={18}/><p>{versions.length?`最近发布：${versions[0].version} · ${versions[0].count} 条记录`:'本数据集尚无发布版本'}<br/>历史版本不会被工作批次覆盖。</p></div></aside>
  </div>
  {receipt&&<div className="dv-publish-receipt"><IconCheck size={25}/><div><h3>发布完成 · {receipt.version}</h3><p>{batch.name} · {receipt.count} 条记录 · {receipt.batchId}</p></div><Button icon={IconDownload} onClick={()=>{exportTextBatch(batch,receipt);onToast(`已生成 ${receipt.count} 条版本记录的下载`)}}>下载版本数据</Button><Button variant="primary" onClick={()=>go('training',{versionId:receipt.id})}>前往训练任务<IconArrowRight size={16}/></Button></div>}
  {publishOpen&&<Modal title={`发布数据版本 ${nextVersion}`} description={`${batch.name} · ${batch.batchId}`} onClose={()=>setPublishOpen(false)} footer={<><Button onClick={()=>setPublishOpen(false)}>取消</Button><Button variant="primary" disabled={!consent||!note.trim()||!ready||alreadyPublished} onClick={publish}>确认发布演示版本</Button></>}><div className="dv-release-stats"><span>纳入 <strong>{counts.approved} 条</strong>审核通过记录，其他 {counts.total-counts.approved} 条留在工作批次</span><Badge>当前修订质量检查通过</Badge></div><Field label="发布说明" required><textarea rows={3} value={note} onChange={event=>setNote(event.target.value)}/></Field><label className="dv-consent"><input type="checkbox" checked={consent} onChange={event=>setConsent(event.target.checked)}/><span>我已确认本批次的记录范围、标签规范和来源。</span></label><p className="dv-help">这是本地演示版本；发布后可以在模型训练中选择同一版本。</p>{error&&<p className="dv-action-error" role="alert">{error}</p>}</Modal>}
  {preview&&<TextVersionPreview batch={batch} version={preview} onClose={()=>setPreview(null)} onNavigate={onNavigate} onToast={onToast}/>}
 </div>;
}
